<script setup lang="ts">
import {localize} from './localization';
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import ZoomViewport from './ZoomViewport.vue';
import type {PatternOverview,Piece} from '../../../packages/schema/index';
const props=defineProps<{overview:PatternOverview;pieces:Piece[];language:'zh'|'en';busy:boolean}>(),emit=defineEmits<{close:[];piece:[id:string]}>();
const zh=computed(()=>props.language==='zh'),chosen=ref(props.overview.pieceIds[0]),dialog=ref<HTMLElement>(),closeButton=ref<HTMLButtonElement>();
const uri=computed(()=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(props.overview.svg));
// Render screen-size outlines in the outer viewport so pale fabrics stay visible.
const outlines=computed(()=>Array.from(new DOMParser().parseFromString(props.overview.svg,'image/svg+xml').querySelectorAll('#Cut path')).map(p=>p.getAttribute('d')??''));
const pieces=computed(()=>props.pieces.filter(p=>props.overview.pieceIds.includes(p.id)));
function key(e:KeyboardEvent){const dialogs=document.querySelectorAll('[role=dialog]');if(dialogs[dialogs.length-1]!==dialog.value)return;if(e.key==='Escape'){e.preventDefault();emit('close');}if(e.key==='Tab'){const list=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not([disabled]),select')??[]).filter(el=>el.getClientRects().length),first=list[0],last=list.at(-1);if(first&&(!dialog.value?.contains(document.activeElement)||e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first)?.focus();}}}
let previous:HTMLElement|null=null;onMounted(()=>{previous=document.activeElement as HTMLElement;closeButton.value?.focus();window.addEventListener('keydown',key);});onBeforeUnmount(()=>{window.removeEventListener('keydown',key);previous?.focus();});
</script>
<template><div class="overview-backdrop" @click.self="emit('close')"><section ref="dialog" role="dialog" aria-modal="true" :aria-label="zh?'选中裁片总览':localize('Selected cut overview')" class="batch-preview"><header><div><strong>{{zh?'选中裁片总览':localize('Selected cut overview')}}</strong><small>{{overview.pieceIds.length}} {{zh?'片 · 保持原始轮廓':localize('pieces · Original contours')}}</small></div><button ref="closeButton" :aria-label="zh?'关闭裁片总览':localize('Close cut overview')" @click="emit('close')">×</button></header><p>{{zh?'屏幕总览自动排布全部裁片。选择一片再查看实际毫米分页；屏幕缩放不改变打印尺寸。':localize('The screen overview arranges every selected cut. Choose a piece for actual-size page tiling. Screen zoom does not change print dimensions.')}}</p><ZoomViewport :view-box="`0 0 ${overview.widthMm} ${overview.heightMm}`" :language="language" label="Selected cut overview" v-slot="{viewBox}"><svg class="overview-board" :viewBox="viewBox" aria-label="选中全部裁片"><image :href="uri" :width="overview.widthMm" :height="overview.heightMm"/><path v-for="(d,i) in outlines" :key="i" :d="d" class="overview-cut" fill="none" stroke="#31566b" stroke-width=".75" vector-effect="non-scaling-stroke"/></svg></ZoomViewport><footer><select v-model="chosen" :aria-label="zh?'选择分页裁片':localize('Choose piece to tile')"><option v-for="p in pieces" :key="p.id" :value="p.id">{{p.name}}</option></select><button :disabled="busy||!chosen" @click="emit('piece',chosen)">{{zh?'单片分页拼接预览':localize('Single-piece page preview')}}</button></footer></section></div></template>
<style scoped>.overview-backdrop{position:fixed;inset:0;z-index:35;background:color-mix(in srgb,var(--studio-deep) 62%,transparent);display:grid;place-items:center;padding:18px}.batch-preview{width:min(1100px,100%);height:min(900px,calc(100vh - 36px));display:flex;flex-direction:column;overflow:hidden;background:var(--panel);border:1px solid var(--border);border-radius:18px}.batch-preview header,.batch-preview footer{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 18px;flex-shrink:0}.batch-preview small{display:block;margin-top:5px}.batch-preview p{font-size:12px;margin:0;padding:0 18px 12px;line-height:1.6;color:var(--text-muted)}.batch-preview :deep(.zoom-viewport){flex:1;min-height:0;display:flex;flex-direction:column}.batch-preview :deep(.zoom-workarea){flex:1;min-height:0}.batch-preview :deep(.zoom-content){min-height:0}.overview-board{display:block;width:100%;height:100%;padding:8px;box-sizing:border-box;background:white}.batch-preview footer select{min-width:0;flex:1}.batch-preview footer button{flex-shrink:0}</style>
